// @line-route /picks
import { ListPage } from '../../../library/pages/ListPage';
import { useEffect, useState } from 'react';
import books from '../../../library/fixtures/books.json';

interface Book { id: string; title: string; author: string; genre: string; year: number; pages: number; summary: string; available: boolean; }

export function PicksPage() {
 const [pickedBooks, setPickedBooks] = useState<Book[]>(JSON.parse(localStorage.getItem('picks')) || []);

 useEffect(() => {
 localStorage.setItem('picks', JSON.stringify(pickedBooks));
 }, [pickedBooks]);

 const handleRemove = (id: string) => {
 setPickedBooks(pickedBooks.filter((book) => book.id !== id));
 };

 return (
 <ListPage title={`My picks (${pickedBooks.length})`}
 toolbar={<button onClick={() => {}} disabled={pickedBooks.length >= 4}>Add to my picks</button>}
 children={pickedBooks.map((book) => (
 <div key={book.id}>
 <h3>{book.title}</h3>
 <p>{book.author}</p>
 <button onClick={() => handleRemove(book.id)}>Remove {book.title}</button>
 </div>
 ))}
 empty={<p>You have not picked any books yet</p>}
 />
 );
}

