// @line-base pages/ListPage
// @line-route /picks
import { ListPage } from '../../../library/pages/ListPage';
import { Button } from '../../../library/components/Button';
import { usePicks } from '../usecases/usePicks';

export function PicksPage() {
  const { picks, removePick } = usePicks();
  const pickedBooks = picks.map((pick) => pick.book);
  const back = <Link href="/">Back to Books</Link>;
  const loanLength = pickedBooks.length <= 2 ? 21 : 14;
  const returnBy = new Date(Date.now() + loanLength * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  return (
    <ListPage title={`My picks (${pickedBooks.length})`} back={back}>
      {pickedBooks.length === 0 ? (
        <p>You have not picked any books yet</p>
      ) : (
        pickedBooks.map((book) => (
          <div key={book.id}>
            <p>{book.title}</p>
            <p>{book.author}</p>
            <Button onClick={() => removePick(book.id)}>Remove {book.title}</Button>
          </div>
        ))
      )}
      <p>Loan length: {loanLength} days</p>
      <p>Return by: {returnBy}</p>
      <Link href="/request">Request these books</Link>
    </ListPage>
  );
}

